// ============================================
// Configuratie — pas deze waarden aan!
// ============================================
const ODOO_URL = 'https://jouw-odoo-url.com';
const ODOO_DB = 'jouw-database';
const ODOO_USER = 'admin';
const ODOO_PASSWORD = 'jouw-api-key';

const input = $input.first().json;
const projectId = parseInt(input.query?.project_id) || null;

if (!projectId) {
  throw new Error('Geen project_id opgegeven.');
}

return [{
  json: {
    config: { url: ODOO_URL, db: ODOO_DB, user: ODOO_USER, password: ODOO_PASSWORD },
    projectId,
    rpc: {
      jsonrpc: '2.0',
      id: 1,
      method: 'call',
      params: {
        service: 'common',
        method: 'authenticate',
        args: [ODOO_DB, ODOO_USER, ODOO_PASSWORD, {}]
      }
    }
  }
}];

// Bouw request om project info op te halen
const authResponse = $input.first().json;
const uid = authResponse.result;
if (!uid) throw new Error('Odoo authenticatie mislukt!');

const setup = $('Setup').first().json;
const { config, projectId } = setup;

return [{
  json: {
    config, uid, projectId,
    rpc: {
      jsonrpc: '2.0',
      id: 2,
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          config.db, uid, config.password,
          'project.project', 'read',
          [[projectId]],
          { fields: ['name', 'partner_id'] }
        ]
      }
    }
  }
}];

// Bouw request om alle taken van het project op te halen
const projectResponse = $input.first().json;
const projectData = (projectResponse.result || [])[0] || {};

const prev = $('Prep Read Project').first().json;
const { config, uid, projectId } = prev;

return [{
  json: {
    config, uid, projectId,
    projectNaam: projectData.name || '',
    projectPartner: projectData.partner_id || '',
    rpc: {
      jsonrpc: '2.0',
      id: 3,
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          config.db, uid, config.password,
          'project.task', 'search_read',
          [[['project_id', '=', projectId]]],
          { fields: ['name', 'stage_id', 'parent_id', 'description'] }
        ]
      }
    }
  }
}];

// Bouw geneste structuur op basis van parent_id en stage_id
const tasksResponse = $input.first().json;
const tasks = tasksResponse.result || [];

const prev = $('Prep Read Tasks').first().json;
const { projectId, projectNaam, projectPartner } = prev;

// Maak lookup: id → task
const taskMap = {};
for (const t of tasks) {
  taskMap[t.id] = t;
}

// Categoriseer op stage naam
const getStage = (t) => {
  if (Array.isArray(t.stage_id)) return t.stage_id[1];
  return '';
};

// Sorteer taken per stage
const blokken = tasks.filter(t => getStage(t) === 'Blokken');
const verdiepen = tasks.filter(t => getStage(t) === 'Verdiepen');
const collectoren = tasks.filter(t => getStage(t) === 'Collectoren');
const kringen = tasks.filter(t => getStage(t) === 'Kringen');

// Helper: haal parent id op
const getParentId = (t) => {
  if (Array.isArray(t.parent_id)) return t.parent_id[0];
  if (typeof t.parent_id === 'number') return t.parent_id;
  return null;
};

// Helper: parse extra data uit description (JSON met _td marker)
const parseDesc = (desc) => {
  if (!desc) return {};
  try {
    // Odoo kan HTML wrappen, strip tags
    const clean = desc.replace(/<[^>]*>/g, '').trim();
    const parsed = JSON.parse(clean);
    if (parsed._td) return parsed;
  } catch (e) {}
  return {};
};

// Bouw kringen per collector
const buildKringen = (collectorId) => {
  return kringen
    .filter(k => getParentId(k) === collectorId)
    .map(k => {
      const naam = k.name || '';
      const numMatch = naam.match(/(\d+)/);
      const nummer = numMatch ? parseInt(numMatch[1]) : 0;
      const extra = parseDesc(k.description);
      return {
        odoo_id: k.id,
        nummer,
        systeem: extra.systeem || '',
        legpatroon: extra.legpatroon || '',
        lengte: extra.lengte || 0,
        m2: extra.m2 || 0
      };
    })
    .sort((a, b) => a.nummer - b.nummer);
};

// Bouw collectoren per verdiep
const buildCollectoren = (verdiepId) => {
  return collectoren
    .filter(c => getParentId(c) === verdiepId)
    .map(c => {
      const naam = c.name || '';
      const numMatch = naam.match(/Collector\s*(\d+)/);
      const nummer = numMatch ? parseInt(numMatch[1]) : 0;
      const collectorNaam = numMatch ? naam.replace(/Collector\s*\d+\s*[-—]?\s*/, '').trim() : naam;
      const extra = parseDesc(c.description);
      const kringenList = buildKringen(c.id);
      return {
        odoo_id: c.id,
        nummer: extra.nummer || nummer || 1,
        naam: collectorNaam,
        druk: extra.druk || 4,
        randisolatie: extra.randisolatie || 0,
        uitzetvoegen: extra.uitzetvoegen || 0,
        aantalKringen: kringenList.length,
        kringen: kringenList
      };
    })
    .sort((a, b) => a.nummer - b.nummer);
};

// Bouw verdiepen per gebouw
const buildVerdiepen = (gebouwId) => {
  return verdiepen
    .filter(v => getParentId(v) === gebouwId)
    .map(v => {
      const naam = v.name || '';
      const numMatch = naam.match(/Verdieping\s*([+-]?\d+)/);
      const nummer = numMatch ? numMatch[1] : '0';
      return {
        odoo_id: v.id,
        nummer,
        collectoren: buildCollectoren(v.id)
      };
    })
    .sort((a, b) => parseInt(a.nummer) - parseInt(b.nummer));
};

// Bouw gebouwen (top level)
const gebouwen = blokken.map(g => {
  const naam = g.name || '';
  return {
    odoo_id: g.id,
    naam,
    verdiepen: buildVerdiepen(g.id)
  };
});

return [{
  json: {
    naam: projectNaam,
    partner_id: projectPartner,
    gebouwen
  }
}];
